insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch1', 'مقدمة في التسويق', 1) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-1', 'اختبار مقدمة في التسويق', 70, '[{"q":"ما هو أقرب تعريف للتسويق حسب الفصل؟","options":["عملية فهم احتياجات العملاء وتصميم منتجات تلبيها والتواصل معهم","مجرد إعلان عن المنتج لجذب المشترين","بيع المنتج بالقوة بعد إنتاجه","زيادة كمية الإنتاج فقط"],"correctIndex":0},{"q":"ماذا تقول القاعدة الذهبية في الفصل عن بداية التسويق؟","options":["التسويق يبدأ بعد الإعلان","التسويق لا يبدأ بالمنتج بل يبدأ بالعميل","التسويق يبدأ دائمًا بالبيع","التسويق يعني إنتاج كميات كبيرة"],"correctIndex":1},{"q":"ما هي الخطوة الأولى من تبسيط تعريف التسويق (خمس خطوات)؟","options":["تحديد السعر المناسب","إيصال المنتج إلى العميل","فهم العميل","بناء علاقة طويلة بعد البيع"],"correctIndex":2},{"q":"أي من العناصر التالية وُصف في الفصل بأنه محور كل شيء في عملية التسويق؟","options":["الطلب","القيمة","الاحتياج","العميل"],"correctIndex":3},{"q":"ما الفرق الزمني بين التسويق والبيع كما ورد في الفصل؟","options":["التسويق يبدأ قبل إنتاج المنتج والبيع بعد إنتاجه","البيع يبدأ قبل إنتاج المنتج والتسويق بعده","كلاهما يبدأ بعد إنتاج المنتج","كلاهما يبدأ قبل الإنتاج"],"correctIndex":0},{"q":"في مثال محل العصائر، أي سلوك يمثل \"تسويق حقيقي\"؟","options":["شراء معدات وانتظار الزبائن دون سؤالهم","سؤال الزبائن عن تفضيلاتهم ثم صنع العصائر وفقًا لإجاباتهم","خفض السعر بشكل عشوائي لجذب المشترين","فتح المحل دون نشر أي معلومات عنه"],"correctIndex":1},{"q":"ما معنى \"القيمة\" بالنسبة للعميل كما جاء في الفصل؟","options":["كم دفع العميل فقط","ما يريده المنافسون","ما يحصل عليه العميل مقارنة بما دفعه","قيمة المنتج في السوق فقط"],"correctIndex":2},{"q":"أي من القدرات التالية تُنسب إلى التسويق الرقمي في الفصل؟","options":["زيادة تكلفة الإعلان بشكل دائم","الاعتماد على المبيعات وجهًا لوجه فقط","إنتاج سلع بدون دراسة العملاء","قياس نتائج الحملات بدقة"],"correctIndex":3},{"q":"أي من العبارات التالية مُدرجة كمفهوم خاطئ عن التسويق في الفصل؟","options":["التسويق يعني الإعلان فقط","التسويق يبني الثقة مع العملاء","التسويق يساعد في الاحتفاظ بالعملاء","التسويق يزيد المبيعات عند استخدامه بشكل صحيح"],"correctIndex":0},{"q":"ما هي المرحلة الأخيرة في تطور التسويق المذكورة في الفصل؟","options":["التركيز على الإنتاج","التسويق الرقمي","التركيز على المنتج","التركيز على البيع"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch2', 'رحلة العميل (Customer Journey)', 2) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-2', 'اختبار رحلة العميل (Customer Journey)', 70, '[{"q":"ما هي المرحلة الأولى في قمع المبيعات (رحلة العميل) المذكورة في الفصل؟","options":["الوعي (Awareness)","الاهتمام (Interest)","النية (Intent)","الشراء (Purchase)"],"correctIndex":0},{"q":"ماذا يقصد بقمع المبيعات (Sales Funnel) حسب الفصل؟","options":["قائمة لميزات المنتج فقط","مراحل نفسية وسلوكية يمر بها العميل قبل الشراء","طريقة للشحن والتوصيل","نظام لتقديم الخصومات"],"correctIndex":1},{"q":"ما هو الهدف الرئيسي من مرحلة الوعي (Awareness)؟","options":["إتمام عملية البيع فورًا","إطلاق برنامج ولاء للعملاء","لفت الانتباه وإثارة الوعي بوجود المشكلة","إرسال تأكيدات الشحن"],"correctIndex":2},{"q":"أي من الطرق التالية تُستخدم عادة لجذب العملاء في مرحلة الوعي؟","options":["مدونات وفيديوهات تعليمية قصيرة","تحسين عملية الخروج والدفع","عرض جداول مقارنة تفصيلية","حملات إعلانية واسعة الانتشار"],"correctIndex":3},{"q":"أي سلوك يدل على أن العميل انتقل إلى مرحلة الاهتمام (Interest)؟","options":["متابعة حساباتك أو زيارة موقعك وقراءة محتوى","وضع المنتج في سلة التسوق","إتمام عملية الدفع","الاشتراك في برنامج إحالة"],"correctIndex":0},{"q":"ما الذي يُقدَّم عادةً لمساعدة العميل في مرحلة التفكير / التقييم (Consideration)؟","options":["رسائل تذكيرية للسلات المتروكة","جداول مقارنة ودراسات حالة","برامج ولاء للعملاء المخلصين","تتبع الشحن فقط"],"correctIndex":1},{"q":"أي إجراء مناسب لمرحلة النية (Intent) لمساعدة العميل على إكمال الشراء؟","options":["نشر مقالات عامة للتوعية","إطلاق برنامج ولاء طويل الأمد","رسائل تذكيرية للسلات المتروكة أو حوافز سريعة","إنشاء مجتمع للعملاء المخلصين"],"correctIndex":2},{"q":"ما هو الهدف الأساسي من مرحلة الاحتفاظ بالعميل (Retention)؟","options":["جذب عملاء جدد فقط","زيادة عدد الإعلانات المدفوعة","تحويل العميل إلى مسوق فوري للعلامة","بناء علاقة قوية لضمان عدم ذهاب العميل للمنافسين"],"correctIndex":3},{"q":"أي مثال يُوضح مرحلة المدافعة / التأييد (Advocacy) حسب قصة أحمد؟","options":["أحمد ينصح زملاءه بحماس ويصبح مدافعًا عن الشركة","أحمد يشتري مرة واحدة ثم يختفي","الشركة تتصل بخدمة العملاء للاطمئنان بعد التوصيل","أحمد يجمع نقاطًا في برنامج ولاء"],"correctIndex":0},{"q":"ما الخلاصة الرئيسية لنجاح مشروعك كما ورد في الفصل؟","options":["النجاح يعتمد فقط على تقديم أقل سعر","النجاح يعتمد على قيادتك للعميل من الغريب إلى المدافع بتقديم القيمة المناسبة في الوقت المناسب","النجاح يعتمد فقط على الإنفاق على الإعلانات","النجاح يعتمد فقط على جودة التغليف"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch3', 'فهم العميل (Customer Understanding)', 3) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-3', 'اختبار فهم العميل (Customer Understanding)', 70, '[{"q":"ما هو السؤال الأساسي في التسويق الناجح وفق الفصل؟","options":["ما سعر المنتج؟","من هو الشخص الذي أبيع له؟","ما لون الشعار؟","ما هي مواصفات المنتج؟"],"correctIndex":1},{"q":"من هو العميل حسب تعريف الفصل؟","options":["أي شخص لديه مشكلة أو حاجة أو رغبة ويبحث عن حل مقابل قيمة","أي شخص يمتلك منتجًا","أي شخص يعمل في التسويق","أي شخص يعرف استخدام الإنترنت"],"correctIndex":0},{"q":"ماذا يشتري العميل في الأساس بحسب الفصل؟","options":["المنتج بحد ذاته","النتيجة أو الفائدة التي يمنحها المنتج","اسم العلامة التجارية","مواصفات المنتج"],"correctIndex":1},{"q":"لماذا اشترى رجل ساعة فاخرة في مثال الفصل؟","options":["لمعرفة الوقت بدقة","للمظهر الراقي والشعور بالنجاح والمكانة","للاستخدام الرياضي","لأنها الأرخص"],"correctIndex":1},{"q":"ما المقصود بـ Buyer Persona في الفصل؟","options":["قائمة أسعار للعملاء","عميل فعلي مسجل في المتجر","وصف تفصيلي لعميل افتراضي يمثل شريحة من العملاء","حساب على فيسبوك"],"correctIndex":2},{"q":"لماذا لا نستهدف الجميع عند التسويق؟","options":["لأن كل منتج يناسب فئة معينة فقط","لأن التسويق مكلف للجميع","لأن الإنترنت محدود","لأن الجميع يكرهون الإعلانات"],"correctIndex":0},{"q":"أي مما يلي ليس من احتياجات العملاء المذكورة في الفصل؟","options":["الأمان","الراحة","النجاح","الطعم المفضل"],"correctIndex":3},{"q":"أي طريقة من التالية ذُكرت لتقليل مخاوف العميل؟","options":["الضمان","زيادة السعر","إخفاء المعلومات","تأخير الدعم"],"correctIndex":0},{"q":"ما المقصود بـ Pain Points في الفصل؟","options":["مشكلات أو آلام تدفع العميل للشراء","ميزات المنتج التقنية","قنوات التسويق","أوقات العمل"],"correctIndex":0},{"q":"أي من الأسئلة العشرة قبل إطلاق الحملة واردة في الفصل؟","options":["ما لون شعار المنافس؟","أين يقضي العميل وقته؟","كم عدد الموظفين لديك؟","ما نوع الخشب المستخدم؟"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch4', 'علم النفس التسويقي (Marketing Psychology)', 4) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-4', 'اختبار علم النفس التسويقي (Marketing Psychology)', 70, '[{"q":"ما هو علم النفس التسويقي؟","options":["علم يدرس كيف يفكر العميل","علم لتصنيع المنتجات","علم لتحديد الأسعار فقط","علم لإدارة المخزون"],"correctIndex":0},{"q":"بحسب الفصل، الناس لا يشترون المنتج نفسه، بل يشترون ماذا؟","options":["المواصفات الفنية للمنتج","الشعور الذي يمنحه المنتج","الضمان فقط","التغليف الجذاب"],"correctIndex":1},{"q":"أي مما يلي ليس من دوافع الشراء المذكورة في الفصل؟","options":["الأمان","الانتماء","الترفيه","تحقيق الذات"],"correctIndex":2},{"q":"إعلانات عيد الأم في الفصل تبيع في الأساس أي مشاعر؟","options":["الخوف","الأمل","الفخر","الحب"],"correctIndex":3},{"q":"في التسويق العصبي، ما الذي يكشفه تتبع حركة العين (Eye Tracking)؟","options":["أين ينظر العميل أولًا","قياس نبض القلب","معرفة السعر المقبول","قياس نشاط الدماغ"],"correctIndex":0},{"q":"عبارة \"لم يتبقَ سوى 3 قطع\" تمثل أي انحياز إدراكي؟","options":["التثبيت السعري","الندرة","الدليل الاجتماعي","تأثير الاختيار الافتراضي"],"correctIndex":1},{"q":"ما المقصود بالقاعدة الذهبية في الفصل بخصوص الرسالة التسويقية؟","options":["التركيز على الصور والموسيقى","التسويق بالعرض الأرخص","جمع الإثارة العاطفية والأدلة المنطقية","الاعتماد على المنتج فقط"],"correctIndex":2},{"q":"أي لون مرتبط عادةً بالثقة والهدوء ويستخدم في البنوك حسب الفصل؟","options":["الأحمر","الأصفر","الأسود","الأزرق"],"correctIndex":3},{"q":"أي وصف يُعتبر أكثر تأثيرًا وفقًا لتأثير الكلمات في الفصل؟","options":["كريم يمنح بشرتك مظهرًا أكثر إشراقًا خلال فترة قصيرة","كريم للبشرة","منتج جديد بعبوة جديدة","سعر ممتاز"],"correctIndex":0},{"q":"وفقًا للفصل، ما الذي يجب أن تُظهره الصورة لتقرب المنتج من العميل؟","options":["صورة المنتج وحده على خلفية بيضاء","المنتج في استخدام حقيقي","قائمة المواصفات الفنية","سعر التخفيض فقط"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch5', 'مبادئ التسويق', 5) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-5', 'اختبار مبادئ التسويق', 70, '[{"q":"ماذا يعني ''Product'' في المزيج التسويقي؟","options":["ما تقدمه الشركة لإشباع حاجة أو حل مشكلة","السعر الذي يدفعه العميل","مكان بيع المنتج","أداة ترويج للمنتج"],"correctIndex":0},{"q":"ماذا يرسل السعر (Price) للعميل بحسب الفصل؟","options":["معلومات عن مكان التوزيع","رسالة عن قيمة المنتج","تفاصيل التغليف والضمان","اسم العلامة التجارية"],"correctIndex":1},{"q":"أي من التالي يُعد عنصراً من عناصر 4Ps؟","options":["People (الأشخاص)","Process (العمليات)","Promotion (الترويج)","Physical Evidence (الدليل المادي)"],"correctIndex":2},{"q":"ما المقصود بـ Place في المزيج التسويقي؟","options":["قيمة المنتج مقارنة بالسعر","تجربة العميل بعد الشراء","طريقة الإعلان عن المنتج","المكان الذي يصل فيه المنتج للعميل"],"correctIndex":3},{"q":"ما هو المقصود بـ Promotion في الفصل؟","options":["الطريقة التي تجعل الناس تعرف المنتج","مكان التوزيع","تغليف المنتج","الميزة البيعية الفريدة"],"correctIndex":0},{"q":"أي عنصر من التالي أُضيف في نموذج 7Ps عند الحديث عن الخدمات؟","options":["Price","People","Product","Promotion"],"correctIndex":1},{"q":"ماذا يعني الحرف S في نموذج STP؟","options":["Targeting (اختيار الجمهور)","Positioning (التموضع)","Segmentation (تقسيم السوق)","Promotion (الترويج)"],"correctIndex":2},{"q":"في نموذج AIDA، ما المرحلة التي تلي Interest (الاهتمام)؟","options":["Attention","Interest","Action","Desire"],"correctIndex":3},{"q":"ما هي أول مرحلة من مراحل قرار الشراء الخمس؟","options":["إدراك المشكلة","البحث","المقارنة","ما بعد الشراء"],"correctIndex":0},{"q":"ما المقصود بـ Value Proposition حسب الفصل؟","options":["مجموعة عناصر 4Ps","سبب يجعل العميل يشتري منك أو القيمة التي يحصل عليها","أداة ترويجية","مكان توزيع المنتج"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch6', 'أنواع التسويق (Marketing Types)', 6) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-6', 'اختبار أنواع التسويق (Marketing Types)', 70, '[{"q":"ما هو التسويق الرقمي (Digital Marketing)؟","options":["استخدام الإنترنت والأجهزة الرقمية للترويج","توزيع مطبوعات ورقية محليًا","الإعلانات التلفزيونية فقط","مبيعات مباشرة بالمنزل"],"correctIndex":0},{"q":"ما هدف التسويق بالمحتوى؟","options":["عرض إعلانات مدفوعة فقط","جذب العملاء عبر محتوى مفيد بدلاً من البيع المباشر","إرسال رسائل نصية قصيرة للعملاء","التركيز على البيع عبر الهاتف"],"correctIndex":1},{"q":"أي من الأنشطة التالية مثال على التسويق عبر وسائل التواصل؟","options":["تحسين ظهور الموقع في نتائج البحث","إرسال تذكير بالمواعيد عبر البريد الإلكتروني","نشر صور المنتجات يومياً والرد على التعليقات","إعلانات مدفوعة في محرك البحث"],"correctIndex":2},{"q":"ما استخدام شائع للتسويق بالبريد الإلكتروني؟","options":["نشر فيديوهات على تيك توك","تحسين محتوى الموقع للمحركات","التعاون مع مؤثرين لتحقيق وعي","إرسال عروض وتذكير بالعربة المهجورة"],"correctIndex":3},{"q":"ما المقصود بـ تحسين محركات البحث (SEO)؟","options":["ظهور الموقع في نتائج البحث بدون إعلانات مدفوعة","إعلانات مدفوعة داخل محركات البحث","التسويق عبر الرسائل النصية","التسويق عبر المؤثرين"],"correctIndex":0},{"q":"ما هو التسويق عبر محركات البحث (SEM)؟","options":["جعل الموقع يظهر في نتائج البحث مجانًا","الإعلان المدفوع داخل محركات البحث","بناء مجتمع من العملاء","التسويق بالبريد التقليدي"],"correctIndex":1},{"q":"ما المقصود بالتسويق بالعمولة (Affiliate Marketing)؟","options":["استخدام مبتكر منخفض التكلفة لشد الانتباه","الاعتماد على المشاهير للترويج","أشخاص يسوقون المنتجات ويحصلون على عمولة عند كل بيع","التسويق المحلي لمدينة محددة"],"correctIndex":2},{"q":"أي جملة تصف التسويق غير التقليدي (Guerrilla Marketing)؟","options":["إعلانات مدفوعة على محركات البحث","إرسال نشرات إخبارية بالبريد الإلكتروني","التركيز على تحسين محركات البحث","أفكار مبتكرة قليلة التكلفة تلفت الانتباه مثل رسم ثلاثي الأبعاد في شارع"],"correctIndex":3},{"q":"ما هدف التسويق المحلي؟","options":["استهداف منطقة جغرافية محددة","جعل المحتوى ينتشر بسرعة عالميًا","التسويق عبر المؤثرين فقط","التسويق للشركات فقط"],"correctIndex":0},{"q":"ما معنى إعادة الاستهداف (Remarketing)؟","options":["إنشاء مجتمع من العملاء والمعجبين","إعادة عرض الإعلانات للأشخاص الذين زاروا موقعك ولم يشتروا","التسويق عبر الهاتف مباشرة","تنظيم فعاليات لتجربة المنتج"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch7', 'أساسيات العلامة التجارية', 7) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-7', 'اختبار أساسيات العلامة التجارية', 70, '[{"q":"ما هي العلامة التجارية كما وردت في الفصل؟","options":["الصورة والانطباع والمشاعر والأفكار التي تتكون في عقل العميل عند سماع اسم شركتك أو رؤية منتجك","اسم وشعار الشركة فقط","مجموعة مواصفات المنتج الفنية","سعر المنتج وقنوات التوزيع"],"correctIndex":0},{"q":"أي مما يلي ليس مذكورًا كمكون من مكونات البراند في الفصل؟","options":["الاسم","الألوان","السعر","الشعار"],"correctIndex":2},{"q":"ما فائدة وجود علامة تجارية قوية وفق الفصل؟","options":["تجعل المنتج أسهل تقليدًا","يتذكرك العملاء ويثقون بك","تخفض قيمة المنتج في الأسواق","تجعل العملاء يتوقفون عن الشراء"],"correctIndex":1},{"q":"أي لون يرمز إلى الفخامة والقوة والرقي حسب الجدول في الفصل؟","options":["الأزرق","الأحمر","الأخضر","الأسود"],"correctIndex":3},{"q":"ما المقصود بالهوية البصرية (Visual Identity)؟","options":["اللغة المرئية التي يتعرف بها الناس على البراند حتى قبل قراءة اسمه","صندوق التغليف فقط","وصف تقني للمنتج","سعر البيع بالتجزئة"],"correctIndex":0},{"q":"لو قيلت عبارة \"لو كانت علامتك التجارية إنسانًا...\" فما الذي يشير إليه الفصل؟","options":["اختيار ألوان الشعار فقط","نوع الخط المستخدم في الشعار","شخصية العلامة التجارية بصفات إنسانية تحدد أسلوبها","قائمة أسعار المنتجات"],"correctIndex":2},{"q":"ما الصفة المطلوبة في وعد العلامة التجارية الجيد كما ورد في الفصل؟","options":["مبهم وغير واقعي","واضح وقابل للتحقيق ويهم العميل","يهم الشركة فقط وليس العميل","يجب تغييره كل فترة لجذب الانتباه"],"correctIndex":1},{"q":"أي من الأمثلة التالية يعد تشكيلًا لتموضع (Positioning) العلامة التجارية؟","options":["اختيار نوع الخط في الشعار","صور الدعاية المستخدمة","نبرة الاتصال في الرسائل","التركيز على أن تكون \"أسرع توصيل\" لتمييز العلامة عن المنافسين"],"correctIndex":3},{"q":"أي مما يلي يزيد من قيمة العلامة التجارية (Brand Equity) بحسب الفصل؟","options":["خدمة العملاء الممتازة","نسخ منتجات المنافسين","خفض جودة المنتج لتقليل التكلفة","التوقف عن التسويق"],"correctIndex":0},{"q":"في مثال علامة القهوة المختصة، ما هو وعد العلامة التجارية المذكور؟","options":["تقديم أرخص قهوة في السوق","التوصيل خلال 24 ساعة لكل الطلبات","حبوب قهوة طازجة ومحمصة بعناية في كل طلب","استخدام ألوان بنية وبيج فقط في الالتزامات"],"correctIndex":2}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
