insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-8', 'اختبار أساسيات كتابة المحتوى (Content Writing Basics)', 70, '[{"q":"ما هو تعريف المحتوى في الفصل؟","options":["نصوص ومقاطع فيديو فقط","شيء يُستهلك دون فائدة","أي معلومة أو رسالة تُقدّم للجمهور بهدف معين","منتج للبيع فقط"],"correctIndex":2},{"q":"أي مما يلي ليس من أهداف كتابة المحتوى المذكورة في الفصل؟","options":["التعليم","بناء الثقة","جمع بيانات العملاء","البناء الضريبي"],"correctIndex":3},{"q":"أي نوع من المحتوى هدفه البيع المباشر؟","options":["الترفيهي","بيعي (Promotional)","خلف الكواليس","المحتوى التحفيزي"],"correctIndex":1},{"q":"ما هو أول مكون في منشور ناجح وفق الفصل؟","options":["المشكلة","القيمة","الحل","Hook (الخطاف) أول سطر يجذب الانتباه"],"correctIndex":3},{"q":"أي من الأمثلة التالية يعد CTA وفق الفصل؟","options":["احفظ المنشور","تجاهل المنشور","اقرأ فقط","لا تفعل شيئًا"],"correctIndex":0},{"q":"في نموذج AIDA، ماذا يعني الحرف D؟","options":["الانتباه (Attention)","الاهتمام (Interest)","العمل (Action)","الرغبة (Desire)"],"correctIndex":3},{"q":"من عناصر القصة التسويقية، من هو البطل عادةً؟","options":["المنتج","العميل","الموظف","المنافس"],"correctIndex":1},{"q":"أي مما يلي يعد خطأ شائعاً في كتابة المحتوى حسب الفصل؟","options":["استخدام عناوين مملة لا تجذب الانتباه","بناء الثقة عبر شهادات العملاء","تقسيم المحتوى إلى فقرات","إضافة CTA في نهاية المحتوى"],"correctIndex":0},{"q":"ما النتيجة المحتملة لاستخدام Storytelling بذكاء؟","options":["يجعل المحتوى أقل تأثيرًا","يزيد من ثقة الجمهور ويجعل المحتوى أكثر تذكرًا","يقلل فرص التفاعل","يزيد من تعقيد الرسالة"],"correctIndex":1},{"q":"أي من العناصر التالية ليس من عناصر الإعلان الناجح المذكورة؟","options":["الخصم فقط بدون شرح للفوائد","عنوان جذاب","المميزات والفوائد","CTA واضح"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
