insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-9', 'اختبار مقدمة في التسويق الرقمي (Digital Marketing Fundamentals)', 70, '[{"q":"ما تعريف الإنترنت كما ورد في الفصل؟","options":["شبكة عالمية تربط مليارات الأجهزة","خدمة دفع إلكتروني","متصفح لزيارة المواقع","محرك بحث"],"correctIndex":0},{"q":"أي جهاز يحتفظ بالموقع ويرسل الصفحات للزوار؟","options":["اسم النطاق","السيرفر","المتصفح","محرك البحث"],"correctIndex":1},{"q":"ما المقصود بـ ''الموقع الإلكتروني'' في سياق التسويق الرقمي؟","options":["محرك بحث متخصص","خدمة الدفع عبر الإنترنت","المنزل الرئيسي للشركة على الإنترنت","عنوان المتجر في الحي"],"correctIndex":2},{"q":"أي منصة تُستخدم عادةً لبناء العلامة والوعي والتفاعل؟","options":["محركات البحث","البريد الإلكتروني","التطبيقات","التواصل الاجتماعي"],"correctIndex":3},{"q":"متى يستخدم الأشخاص محركات البحث حسب الفصل؟","options":["عندما يريدون بناء الوعي","عندما يريدون شراء شيء","للتواصل مع الأصدقاء","لمشاهدة الفيديوهات"],"correctIndex":1},{"q":"أي نوع إعلان يظهر عندما يبحث العميل ويستهدف نية الشراء؟","options":["إعلانات الفيديو","الإعلانات المصورة","إعلانات البحث","إعلانات التطبيقات"],"correctIndex":2},{"q":"ما معنى إعادة الاستهداف (Remarketing) وفق الفصل؟","options":["عرض الإعلان لنفس الشخص بعد زيارته المتجر دون شراء","إرسال بريد إلكتروني تلقائي للعميل بعد الشراء","إظهار الإعلان فقط لمستخدمي التطبيقات","إنشاء إعلانات تبدو كجزء من المحتوى"],"correctIndex":0},{"q":"أي من العوامل التالية ذُكر كمعيار لاختيار المنصة الرقمية؟","options":["طول اسم النطاق","ميزانيتك","حجم السيرفر","لغة البرمجة"],"correctIndex":1},{"q":"في أي مرحلة من مسار العميل يضيف المنتج إلى السلة لكنه لم يكمل الشراء؟","options":["الاهتمام","الوعي","النية","الشراء"],"correctIndex":2},{"q":"ما الدرس الرئيسي الذي يشدد عليه الفصل فيما يتعلق بهدف المسوق؟","options":["الاعتماد فقط على إعلان واحد","استخدام سيرفرات كبيرة فقط","التركيز فقط على البيع المباشر","بناء تجربة متكاملة وتحويل العميل إلى سفير للعلامة"],"correctIndex":3}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into projects (course_id, project_key, title, instructions, passing_score) values ((select id from courses where slug='marketing-launch'), 'graduation-project', 'مشروع التخرج — Marketing Launch', 'أنشئ خطة إطلاق تسويقية متكاملة لمنتج أو خدمة حقيقية أو افتراضية. وضّح العميل المثالي، القيمة المقترحة، الهوية، القنوات، المحتوى، الإعلانات، الميزانية، مؤشرات القياس، ورحلة العميل.', 70) on conflict (course_id, project_key) do update set title=excluded.title, instructions=excluded.instructions, passing_score=excluded.passing_score;
