insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-1', 'اختبار أساسيات استراتيجية النمو التسويقي', 70, '[{"q":"ما السؤال الذي تجيب عنه الاستراتيجية حسب الفصل؟","options":["كيف سأبيع؟","متى أطلق الحملة؟","لماذا سيشتري العميل مني وليس من غيري؟","ما سعر المنتج؟"],"correctIndex":2},{"q":"ما هو تحليل السوق؟","options":["تصميم حملة إعلانية","دراسة السوق لمعرفة حجم السوق واحتياجات العملاء وسلوكهم","تحديد سعر المنتج فقط","إنشاء موقع إلكتروني"],"correctIndex":1},{"q":"أي مما يلي يعد عنصراً أساسياً في تحليل السوق؟","options":["حجم السوق","سلاسل التوريد الدولية","التسليم أو التوزيع","إدارة الموارد البشرية"],"correctIndex":0},{"q":"في مثال كورس التسويق بالإمارات، ما الذي عُدّ \"السوق الحقيقي\"؟","options":["200 ألف يبحثون","50 ألف مستعدون للدفع","10 آلاف يناسبهم سعرك","كل من لديه إنترنت"],"correctIndex":2},{"q":"ما الهدف الأساسي من تحليل المنافسين؟","options":["نسخ منتجاتهم بالضبط","التخلص من المنافسة قانونياً","تحديد رواتب الموظفين","معرفة ماذا يفعلون ولماذا نجحوا وكيف أتفوق عليهم"],"correctIndex":3},{"q":"ماذا يمثل حرف O في نموذج SWOT؟","options":["نقاط القوة (Strengths)","الفرص (Opportunities)","نقاط الضعف (Weaknesses)","التهديدات (Threats)"],"correctIndex":1},{"q":"أي مما يلي يعتبر عاملاً تكنولوجيًا في تحليل PESTEL؟","options":["التضخم","ضرائب جديدة","الذكاء الاصطناعي","قوانين حماية المستهلك"],"correctIndex":2},{"q":"أي من التالي يعد إحدى قوى بورتر الخمس؟","options":["تهديد المنتجات البديلة","تطوير المنتج الداخلي","التسويق عبر السوشيال","سلسلة القيمة"],"correctIndex":0},{"q":"أي من التالي يعد نشاطًا أساسيًا في سلسلة القيمة؟","options":["الموارد البشرية","التكنولوجيا","المشتريات","التسليم أو التوزيع"],"correctIndex":3},{"q":"ما الفائدة الرئيسية من إجراء تحليلات السوق والمنافسين وSWOT وPESTEL قبل الإطلاق؟","options":["تأجيل الإطلاق إلى أجل غير مسمى","خفض جودة المنتج","اتخاذ قرارات مبنية على البيانات بدل التخمين","زيادة سعر المنتج بلا سبب"],"correctIndex":2}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
