insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-2', 'اختبار الهوية والعلامة التجارية', 70, '[{"q":"ما معنى الهوية التجارية كما ورد في الفصل؟","options":["تعني فقط الشعار والألوان","تعني فقط تصميم الموقع والتغليف","الشخصية الكاملة التي يرى بها العملاء علامتك التجارية ويشعرون بها","تعني فقط عناصر مرئية بسيطة"],"correctIndex":2},{"q":"ما هو تصميم البراند (Brand Design) وفق الفصل؟","options":["الجانب البصري للهوية التجارية، كل ما يراه العميل","الصفات الإنسانية للعلامة التجارية","الرسائل الإعلانية فقط","سياسات التسعير والخصومات"],"correctIndex":0},{"q":"أي من التالي ليس من عناصر تصميم البراند المذكورة في الفصل؟","options":["الشعار","الألوان","أسلوب الصور","سياسات التسعير"],"correctIndex":3},{"q":"أي من الصفات التالية يصف شعارًا جيدًا حسب الفصل؟","options":["معقد وصعب التذكر","بسيط وسهل التذكر","يعتمد على ألوان كثيرة ومتضاربة","مناسب لحجم واحد فقط"],"correctIndex":1},{"q":"ما الشعور المرتبط باللون الأزرق بحسب الفصل؟","options":["الحماس والإبداع","الفخامة","الثقة والأمان","الطبيعة والنمو"],"correctIndex":2},{"q":"ماذا يعبر نوع الخط (Typography) عن العلامة التجارية؟","options":["يحدد سعر المنتج","يحدد موقع المنافسين","يحدد مدة التسليم","يعبر عن شخصية البراند"],"correctIndex":3},{"q":"ما هي شخصية البراند كما فُسرت في الفصل؟","options":["الصفات الإنسانية التي تعطيها لعلامتك التجارية","قائمة المنتجات المتاحة","مجموعة الألوان للشعار فقط","سياسة التسعير والخصومات"],"correctIndex":0},{"q":"أي من العناصر التالية هو جزء من مكونات الرسالة التسويقية الناجحة؟","options":["تصميم الشعار فقط","جذب الانتباه","تحديد الموردين","تقسيم الأرباح"],"correctIndex":1},{"q":"ما المقصود بلغة البراند (Brand Voice)؟","options":["شعار بصري للعلامة التجارية","لون موقع الويب","الطريقة التي تتحدث بها العلامة التجارية مع جمهورها","سياسة الإرجاع والاستبدال"],"correctIndex":2},{"q":"لماذا تعتبر القيم مهمة حسب الفصل؟","options":["لأنها تحدد المبادئ التي تؤمن بها العلامة التجارية وتؤثر في قراراتها","لأنها تحدد سعر المنتج فقط","لأنها تحدد حجم المواد التعليمية","لأنها تحدد عدد الموظفين"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
