insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-3', 'اختبار صناعة المحتوى', 70, '[{"q":"ما الذي يجب أن تجيب عنه كل قطعة محتوى احترافي؟","options":["ما الهدف من هذا المحتوى؟","كم عدد المتابعين؟","أين موقع الاستضافة؟","من صمم الصورة؟"],"correctIndex":0},{"q":"ما المقصود بـ \"استراتيجية المحتوى\" وفق الفصل؟","options":["خطة لنشر الصور فقط","خريطة طريق تحدد ماذا لمن وأين ومتى ولماذا تنشر","قائمة بالهاشتاقات الشائعة","تقويم يومي للمحتوى فقط"],"correctIndex":1},{"q":"أيهما يعد خطوة من خطوات بناء استراتيجية المحتوى؟","options":["تحديد سعر المنتج","تصميم شعار الشركة","معرفة الجمهور","فتح متجر إلكتروني"],"correctIndex":2},{"q":"أي منصة من التالية تُناسب المحتوى الطويل بحسب الفصل؟","options":["TikTok للفيديوهات القصيرة","Instagram للصور فقط","LinkedIn للنصائح القصيرة فقط","YouTube للمحتوى الطويل"],"correctIndex":3},{"q":"ما هي \"Content Pillars\" كما وردت في الفصل؟","options":["الموضوعات الرئيسية التي تدور حولها منشوراتك","قوالب التصميم للمنشورات","مجموعات الهاشتاقات","قوائم المؤثرين"],"correctIndex":0},{"q":"أي من الخيارات التالية ليس من أعمدة المحتوى المذكورة في الفصل؟","options":["المحتوى التعليمي","المحتوى الصوتي (بودكاست)","قصص النجاح","المحتوى التفاعلي"],"correctIndex":1},{"q":"لماذا نستخدم تقويم المحتوى (Content Calendar)؟","options":["للترويج المدفوع فقط","لحفظ ملفات الوسائط","لتحديد ماذا ستنشر ومتى وعلى أي منصة ومن المسؤول","لتصميم الشعارات"],"correctIndex":2},{"q":"ما الفرق بين Copywriting والكتابة العادية وفق الفصل؟","options":["الكتابة الإقناعية تعرض معلومات تاريخية","الكتابة الإقناعية أطول دومًا","الكتابة الإقناعية تستخدم كلمات معقدة","الكتابة الإقناعية تدفع العميل لاتخاذ إجراء"],"correctIndex":3},{"q":"ما هو الـ Hook حسب شرح الفصل؟","options":["أول جملة أو أول ثلاث ثوانٍ تجذب انتباه المشاهد","نهاية الفيديو التي تحتوي على شعار","وصف المنشور التفصيلي","قائمة الكلمات المفتاحية"],"correctIndex":0},{"q":"ما هو العنصر الأخير في هيكل السكريبت الاحترافي المذكور؟","options":["Hook","الدعوة لاتخاذ إجراء (CTA)","المشكلة","الإثبات"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
