insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-4', 'اختبار التسويق عبر المنصات الاجتماعية', 70, '[{"q":"ما الخطأ الشائع الذي ذكره الفصل عند النشر على منصات متعددة؟","options":["نشر نفس المحتوى على جميع المنصات دون تعديل","التحليل الدائم لنتائج الحملات","الاعتماد فقط على البث المباشر","تركيز المحتوى على الفيديوهات فقط"],"correctIndex":0},{"q":"ما الاستخدام المناسب لفيسبوك وفق الفصل؟","options":["بناء هوية بصرية فقط","بناء مجتمع حول العلامة التجارية","منصة للانتشار السريع للفيديوهات القصيرة","محرك بحث بصري للأفكار"],"correctIndex":1},{"q":"ما الذي يميز إنستغرام بحسب الفصل؟","options":["منصة مهنية للشركات","منصة للأخبار والنقاشات","تركيز على المحتوى البصري مثل الصور والفيديوهات القصيرة","محرك بحث للفيديوهات الطويلة"],"correctIndex":2},{"q":"ما أفضل ممارسة مذكورة لفيديوهات تيك توك؟","options":["نشر مقالات طويلة على الحساب","الرد على التعليقات بسرعة","الحفاظ على هوية بصرية ثابتة","اجذب الانتباه خلال أول ثلاث ثوانٍ"],"correctIndex":3},{"q":"ما الجمهور المناسب لمنصة LinkedIn حسب الفصل؟","options":["B2B والمهنيون","المراهقون والشباب","المهتمون بالموضة والسفر","الصحفيون ورواد الأعمال"],"correctIndex":0},{"q":"ما نقطة القوة الرئيسية في Pinterest وفق الفصل؟","options":["وصول عضوي سريع وانتشار","عمر المحتوى طويل ويجلب زيارات للموقع","أقوى منصة إعلانية","إنشاء مجتمعات عبر المجموعات"],"correctIndex":1},{"q":"أي مما يلي يعد خطأ شائعًا في التسويق عبر السوشيال ميديا حسب الفصل؟","options":["استخدام صور احترافية دائمًا","اتباع قاعدة 80/20 للمحتوى","التركيز على عدد المتابعين فقط","تحليل النتائج وتحسين الأداء"],"correctIndex":2},{"q":"ماذا تنص قاعدة 80/20 في استراتيجية النشر المذكورة؟","options":["80% بيع و20% محتوى يقدم قيمة","نشر نفس المحتوى عبر جميع المنصات","الاعتماد على الإعلانات فقط","80% محتوى يقدم قيمة و20% محتوى يركز على البيع"],"correctIndex":3},{"q":"ما العامل الأهم عند اختيار المنصة المناسبة؟","options":["جمهورك وأهدافك وليس شهرة المنصة","التواجد في كل المنصات دائمًا","عدد المتابعين فقط","نشر نفس المحتوى على الجميع"],"correctIndex":0},{"q":"ما من مميزات YouTube المذكورة في الفصل؟","options":["منصة للنصوص القصيرة والمناقشات","عمر المحتوى طويل وظهور في نتائج البحث وبناء ثقة","محتوى يومي يختفي بعد فترة","خوارزمية تمنح فرصًا للحسابات الجديدة للانتشار السريع"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
