insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-5', 'اختبار الإعلانات المدفوعة وتحسين الحملات', 70, '[{"q":"ما هي الإعلانات الممولة حسب الفصل؟","options":["إعلانات تدفع مقابل عرضها لجمهور معين على الإنترنت","منشورات عضوية على صفحات التواصل الاجتماعي","قوائم مجانية على محركات البحث","نشرات بريد إلكتروني داخلية"],"correctIndex":0},{"q":"أي منصة تتضمن Facebook وInstagram وMessenger وAudience Network؟","options":["Google Ads","Meta Ads","TikTok Ads","LinkedIn Ads"],"correctIndex":1},{"q":"متى يُنصح باستخدام Google Ads وفق الفصل؟","options":["عندما يبحث العميل بالفعل عن المنتج في محرك البحث","للوصول إلى المديرين التنفيذيين فقط","لإنشاء فيديوهات قصيرة تجذب الانتباه بسرعة","لنشر إعلانات داخل تطبيقات التواصل فقط"],"correctIndex":0},{"q":"أي نوع استهداف يُعرض فيه الإعلان لأشخاص زاروا الموقع أو بدأوا عملية شراء ولم يُكملوا؟","options":["الاستهداف الديموغرافي","الاستهداف بالاهتمامات","إعادة الاستهداف (Remarketing)","الجمهور المشابه (Lookalike)"],"correctIndex":2},{"q":"ما هي النصيحة المقدمة حول كيف تبدأ بالميزانية؟","options":["ابدأ بميزانية صغيرة لاختبار الجمهور والتصميم والنص","ابدأ بميزانية كبيرة للحصول على نتائج سريعة","ضع كل الميزانية في إعلان واحد فقط","تجنب اختبار أكثر من نسخة للإعلان"],"correctIndex":0},{"q":"أي مؤشر أداء يقيس تكلفة النقرة الواحدة؟","options":["CTR","CPC","CPA","ROAS"],"correctIndex":1},{"q":"ما هو الهدف الأساسي لحملات المبيعات (Conversions/Sales)؟","options":["زيادة الوعي بالعلامة التجارية","زيادة التفاعل مثل الإعجابات والتعليقات","إرسال زيارات إلى الموقع فقط","تحويل الزائر إلى عميل يدفع"],"correctIndex":3},{"q":"ما هو أفضل نوع محتوى مذكور للفوز بإعلانات TikTok؟","options":["فيديو قصير","إعلانات بحث نصية","لافتات عرض ثابتة (Display Banners)","منشورات مهنية على LinkedIn"],"correctIndex":0},{"q":"أيهما يعتبر خطأ شائع في الإعلانات الممولة حسب الفصل؟","options":["زيادة الميزانية قبل اختبار الإعلان","اختيار هدف حملة يتناسب مع الهدف الحقيقي","اختبار أكثر من نسخة للإعلان","متابعة مؤشرات الأداء"],"correctIndex":0},{"q":"ما هي الخطوة الأولى في رحلة الإعلان الناجح؟","options":["تصميم إعلان جذاب","تحديد الهدف","إطلاق الحملة","تحليل النتائج"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-growth'), 'ch6', 'تحسين الظهور في محركات البحث SEO', 6) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-6', 'اختبار تحسين الظهور في محركات البحث SEO', 70, '[{"q":"ما هو SEO؟","options":["مجموعة من الممارسات تساعد الموقع على الظهور في النتائج الأولى عندما يبحث المستخدم عن كلمات مرتبطة بما تقدمه.","برنامج إعلاني مدفوع لزيادة الزيارات.","تصميم واجهة المستخدم للموقع فقط.","خدمة استضافة المواقع."],"correctIndex":0},{"q":"أي من التالي ليس مرحلة من مراحل عمل Google المذكورة في الفصل؟","options":["الزحف (Crawling)","الفهرسة (Indexing)","ترتيب النتائج (Ranking)","الإعلان الممول (Paid advertising)"],"correctIndex":3},{"q":"ما هي وظيفة الوصف (Meta Description) في صفحة نتائج البحث؟","options":["تحسين سرعة تحميل الصفحة.","تحديد صفحات الممنوعة للروبوتات.","تشجيع المستخدم على الضغط على النتيجة.","ربط صفحات الموقع ببعضها."],"correctIndex":2},{"q":"ماذا يعني Alt Text بالنسبة للصور؟","options":["اسم ملف الصورة.","عنوان الصفحة في نتائج البحث.","رابط داخلي للصورة.","وصف للصورة يساعد محركات البحث."],"correctIndex":3},{"q":"أي مما يلي يعد عنصرًا من عناصر On-Page SEO؟","options":["العنوان (Title) داخل الصفحة.","الروابط الخلفية من مواقع أخرى.","مشاركة المحتوى على وسائل التواصل.","شراء روابط من مواقع عشوائية."],"correctIndex":0},{"q":"ما هو Off-Page SEO كما ورد في الفصل؟","options":["تحسين العناصر داخل صفحات موقعك.","كل ما يحدث خارج موقعك ويعزز سمعته وثقة محركات البحث به.","الجانب التقني لموقعك مثل سرعة الموقع.","كتابة عناوين H1 وH2 داخل المقال."],"correctIndex":1},{"q":"ما وظيفة خريطة الموقع (XML Sitemap)؟","options":["منع روبوتات البحث من الوصول إلى صفحات معينة.","جعل الموقع أكثر أمانًا عبر HTTPS.","ملف يساعد Google على اكتشاف صفحات الموقع بسهولة.","ضغط صور الموقع تلقائيًا."],"correctIndex":2},{"q":"أي من هذه أمثلة الكلمات الطويلة (Long-tail) كما في الفصل؟","options":["تسويق","يوتيوب","SSL","أفضل كورس لتعلم التسويق الرقمي للمبتدئين."],"correctIndex":3},{"q":"ما نوع نية البحث عندما يكتب المستخدم: \"ما هو SEO؟\"؟","options":["معلوماتية (Informational)","تنقلية (Navigational)","تجارية (Commercial Investigation)","شرائية (Transactional)"],"correctIndex":0},{"q":"ما هي ممارسة يجب تجنبها عند الحصول على Backlinks؟","options":["كتابة محتوى مميز يستحق المشاركة.","شراء الروابط.","نشر مقالات استضافية في مواقع متخصصة.","التعاون مع مدونات في نفس المجال."],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
