insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-7', 'اختبار التسويق عبر البريد الإلكتروني', 70, '[{"q":"ما هو Email Marketing؟","options":["استخدام البريد الإلكتروني للتواصل مع العملاء بهدف تقديم قيمة وبناء ثقة وزيادة المبيعات","نشر الإعلانات الممولة على وسائل التواصل الاجتماعي","إرسال رسائل نصية SMS للعملاء","طباعة كتالوجات وإرسالها بالبريد"],"correctIndex":0},{"q":"أي مما يلي ذُكر كسبب لأهمية Email Marketing في الفصل؟","options":["يزيل الحاجة لبناء علاقة مع العميل","تكلفة منخفضة مقارنة بالإعلانات","لا يمكن قياس نتائجه","يصل فقط عبر الوسائط المطبوعة"],"correctIndex":1},{"q":"ما هي قائمة البريد الإلكتروني؟","options":["قائمة تضم أرقام هواتف العملاء فقط","مجموعة من العملاء الذين تم شراء بياناتهم من مصادر أخرى","مجموعة من الأشخاص الذين وافقوا على استلام رسائلك","سجل للموقع يشمل كل زوار الصفحة"],"correctIndex":2},{"q":"لماذا يعتبر شراء قوائم بريد إلكتروني ممارسة سيئة؟","options":["يزيد معدلات الفتح بشكل دائم","يضمن وصول رسائلك إلى صندوق الوارد","يوفر وقت البناء القائم على الموافقة","قد يؤدي إلى انخفاض سمعة البريد واعتباره مزعجًا (Spam)"],"correctIndex":3},{"q":"أين يوضع نموذج الاشتراك عادةً؟","options":["في الموقع أو المدونة أو صفحة الهبوط","في متاجر البيع فقط","في الرسائل النصية القصيرة فقط","على بطاقات العمل المطبوعة فقط"],"correctIndex":0},{"q":"أي مما يلي يعد هدية مجانية (Lead Magnet) مذكورة في الفصل؟","options":["إرسال رسائل تسويقية كل يوم","كتاب إلكتروني أو دليل مجاني","شراء حملات إعلانية مدفوعة","قائمة عملاء مشترين جاهزة"],"correctIndex":1},{"q":"ما هي الأتمتة (Automation) في Email Marketing؟","options":["إرسال بريد إلكتروني واحد إلى جميع المشتركين يدويًا","نشر محتوى على المدونة تلقائيًا","إرسال رسائل تلقائيًا بناءً على تصرفات العميل","طباعة فواتير الشحن يدويًا"],"correctIndex":2},{"q":"أي من الأمثلة التالية ذُكرت كأتمتة؟","options":["إرسال كتالوج ورقي بالأسابيع","نشر منشور على وسائل التواصل كل ساعة","طلب شراء قوائم بريد إلكتروني","رسالة ترحيب تُرسل تلقائيًا عند الاشتراك"],"correctIndex":3},{"q":"ما هو الهدف من Segmentation (تقسيم الجمهور)؟","options":["تقسيم القائمة لإرسال رسائل مختلفة لكل فئة حسب صفاتهم أو سلوكهم","إرسال نفس الرسالة لجميع المشتركين دون تمييز","حذف المشتركين غير النشطين فقط","زيادة عدد الرسائل المرسلة يوميًا"],"correctIndex":0},{"q":"أي مؤشر يقيس عدد الأشخاص الذين ضغطوا على رابط داخل الرسالة؟","options":["معدل الفتح (Open Rate)","معدل النقر (Click Rate)","معدل الارتداد (Bounce Rate)","معدل إلغاء الاشتراك"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
