insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-8', 'اختبار صفحات الهبوط وتحسين التحويل', 70, '[{"q":"ما هي صفحة الهبوط (Landing Page) حسب الفصل؟","options":["صفحة ويب مصممة لتحقيق هدف واحد فقط","الصفحة الرئيسية للموقع التي تعرض الشركة بالكامل","متجر إلكتروني يضم منتجات متعددة","صفحة اتصل بنا فقط"],"correctIndex":0},{"q":"ما الفرق الأساسي بين الصفحة الرئيسية وصفحة الهبوط؟","options":["الصفحة الرئيسية تقلل الخيارات لتوجيه الزائر","صفحة الهبوط تركز على هدف واحد لتحقيق التحويل","الصفحة الرئيسية تعرض عرضًا واحدًا فقط","صفحة الهبوط تحتوي على عدة روابط للتنقل"],"correctIndex":1},{"q":"أحد مواقف استخدام Landing Page المذكورة في الفصل هو:","options":["للتعريف بالعلامة التجارية بالكامل","لإنشاء صفحات داخلية متعددة للتصفح","الحملات الإعلانية لجلب تحويلات محددة","لوضع قائمة روابط للموقع"],"correctIndex":2},{"q":"أي عنصر يُفضَّل أن يظهر أكثر من مرة في صفحة هبوط طويلة؟","options":["العنوان الرئيسي","العنوان الفرعي","صورة أو فيديو","زر الدعوة لاتخاذ إجراء (CTA)"],"correctIndex":3},{"q":"ما الهدف من عرض القيمة (Value Proposition) في صفحة الهبوط؟","options":["الإجابة على سؤال العميل: لماذا أختارك أنت؟","سرد المواصفات التقنية فقط","عرض جميع صفحات الموقع","تقديم قائمة بالأسعار دون فوائد"],"correctIndex":0},{"q":"أي مما يلي يمثل فائدة (وليس ميزة) حسب أمثلة الفصل؟","options":["60 درسًا","ستتعلم جميع المهارات المطلوبة للعمل في مجال التسويق","صور عالية الجودة للمنتج","ألوان البراند المستخدمة في التصميم"],"correctIndex":1},{"q":"ما معنى CRO كما ورد في الفصل؟","options":["تصميم واجهة المستخدم فقط","قياس جودة الصور على الصفحة","تحسين معدل التحويل لزيادة الأشخاص المنفذين للهدف","زيادة عدد صفحات الموقع"],"correctIndex":2},{"q":"ما الذي يقوم عليه اختبار A/B Testing عادةً؟","options":["إعادة تصميم كامل للموقع للمقارنة","إنشاء صفحات منفصلة لمنتجات مختلفة","زيادة ميزانية الإعلان لمقارنة النتائج","إنشاء نسختين وتغيير عنصر واحد فقط لمقارنة الأداء"],"correctIndex":3},{"q":"ما الفائدة الرئيسية من استخدام Heatmaps بحسب الفصل؟","options":["توضح أين يضغط المستخدم وأين يقضي وقتًا في الصفحة","تُسرّع تحميل الصفحة تلقائيًا","تُنشئ محتوى جديدًا تلقائيًا","تُزيل الحاجة لاختبارات A/B"],"correctIndex":0},{"q":"أي من التالي يُعد خطأ شائعًا في صفحات الهبوط مذكورًا في الفصل؟","options":["تكرار زر CTA في عدة أماكن","وجود أكثر من هدف داخل الصفحة يشتت الزائر","استخدام Heatmaps لتحليل سلوك الزوار","جعل الصفحة متوافقة مع الهاتف"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
