insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-growth'), 'quiz-9', 'اختبار بناء مسارات التحويل Funnels', 70, '[{"q":"لماذا سُمّي مسار التحويل \"Funnel\" (القمع)؟","options":["لأن عدد الأشخاص يقل تدريجيًا من البداية حتى يصل المشترون","لأنه يشبه وعاء الطهي لمزج المحتوى","لأنه يُستخدم في البناء والتشييد","لأنه اسم خاص بأنظمة الدفع الإلكترونية"],"correctIndex":0},{"q":"ما هي أول مرحلة في أي Funnel؟","options":["الاهتمام (Interest)","بناء الثقة (Consideration)","جذب الانتباه (Awareness)","اتخاذ القرار (Conversion)"],"correctIndex":2},{"q":"ما الهدف الرئيسي من Lead Funnel؟","options":["بيع المنتج مباشرة","جمع بيانات العملاء المحتملين (مثل البريد والهاتف)","زيادة متوسط قيمة الطلب","تقديم ويبينار فقط"],"correctIndex":1},{"q":"ما هي المرحلة الثانية في خطوات Lead Funnel؟","options":["إعلان أو محتوى مجاني","إدخال البريد الإلكتروني","هدية مجانية (مثل كتاب إلكتروني)","صفحة هبوط"],"correctIndex":3},{"q":"أي من التالي يُعد عنصرًا من عناصر Sales Funnel المذكورة في الفصل؟","options":["إثبات اجتماعي (آراء العملاء)","لوحة تحكم إدارية للموقع","نظام محاسبة داخلي","تصميم شعار العلامة التجارية"],"correctIndex":0},{"q":"ما ميزة استخدام Webinar Funnel؟","options":["يجمع بيانات العملاء فقط دون بناء علاقة","يبني ثقة كبيرة ويُظهر خبرتك أمام العملاء","يقلل معدل التحويل عادةً","يلغي الحاجة لأي متابعة بعد العرض"],"correctIndex":1},{"q":"ما المقصود بـ Cross-sell كما ورد في الفصل؟","options":["بيع نسخة أغلى من نفس المنتج (Upsell)","إقناع العميل بترك تقييم للمنتج","اقتراح منتج مكمل للعميل","إرجاع المنتج واستبداله"],"correctIndex":2},{"q":"أي مؤشر أداء يقيس متوسط المبلغ الذي ينفقه العميل في كل عملية شراء؟","options":["معدل التحويل (Conversion Rate)","تكلفة الحصول على العميل (CAC)","متوسط قيمة الطلب (Average Order Value - AOV)","معدل التخلي (Drop-off Rate)"],"correctIndex":2},{"q":"ما من الأخطاء الشائعة في بناء Funnels المذكورة في الفصل؟","options":["محاولة البيع مباشرة دون بناء الثقة","تقليل خطوات التسجيل والشراء لتسهيل العملية","متابعة العملاء الذين لم يشتروا","اختبار وتحسين الفانل باستمرار"],"correctIndex":0},{"q":"كيف تساعد العلاقة بين أنواع الـ Funnels في المشروع؟","options":["تعمل كمسارات منفصلة لا تتكامل","تزيد الاعتماد على الحظ في المبيعات","تقلل من متابعة بيانات الأداء","تعمل معًا لتكوين نظام مبيعات يعمل باستمرار"],"correctIndex":3}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into projects (course_id, project_key, title, instructions, passing_score) values ((select id from courses where slug='marketing-growth'), 'graduation-project', 'مشروع التخرج — Marketing Growth', 'أنشئ خطة نمو تسويقي متكاملة لمنتج أو خدمة حقيقية أو افتراضية. وضّح الجمهور، استراتيجية النمو، الهوية، المحتوى، المنصات، الإعلانات، SEO، البريد الإلكتروني، صفحة الهبوط، ومسار التحويل، مع مؤشرات قياس واضحة.', 70) on conflict (course_id, project_key) do update set title=excluded.title, instructions=excluded.instructions, passing_score=excluded.passing_score;
